package org.telegram.ui;
import android.content.Context;import android.view.Gravity;import android.view.View;import android.widget.FrameLayout;import org.telegram.messenger.DevGramPlugins;import org.telegram.messenger.R;import org.telegram.ui.ActionBar.*;import org.telegram.ui.Components.*;import java.util.ArrayList;
public class DevGramPluginReportsActivity extends BaseFragment{
 private final ArrayList<DevGramPlugins.PluginReport> reports=new ArrayList<>();private UniversalRecyclerView list;
 @Override public View createView(Context c){actionBar.setBackButtonImage(R.drawable.ic_ab_back);actionBar.setTitle("Жалобы на плагины");actionBar.setActionBarMenuOnItemClick(new ActionBar.ActionBarMenuOnItemClick(){@Override public void onItemClick(int id){if(id==-1)finishFragment();}});FrameLayout root=new FrameLayout(c);list=new UniversalRecyclerView(this,this::fill,this::click,null);list.setBackgroundColor(Theme.getColor(Theme.key_windowBackgroundGray,resourceProvider));root.addView(list,LayoutHelper.createFrame(-1,-1,Gravity.FILL));DevGramPlugins.fetchPluginReports(x->{reports.clear();reports.addAll(x);list.adapter.update(true);});return fragmentView=root;}
 private void fill(ArrayList<UItem> items,UniversalAdapter a){items.add(UItem.asHeader("Открытые жалобы"));if(reports.isEmpty()){items.add(UItem.asShadow("Жалоб на плагины нет."));return;}for(int i=0;i<reports.size();i++){DevGramPlugins.PluginReport r=reports.get(i);items.add(UItem.asButton(i,R.drawable.msg_report,r.pluginId,r.reason+" · пользователь "+r.reporterId));}items.add(UItem.asShadow(null));}
 private void click(UItem item,View v,int p,float x,float y){if(item.id<0||item.id>=reports.size())return;DevGramPlugins.PluginReport r=reports.get(item.id);new AlertDialog.Builder(getParentActivity()).setTitle("Жалоба на "+r.pluginId).setMessage(r.reason).setItems(new CharSequence[]{"Закрыть жалобу","Скрыть плагин"},(d,w)->{if(DevGramPlugins.resolvePluginReport(r,w==1)){reports.remove(r);list.adapter.update(true);}}).setNegativeButton("Отмена",null).show();}
}
